RRB.load({"id":"ntpc-2025-aug-29-s1","exam":"ntpc","label":"NTPC UG CBT 1 · 29 Aug 2025 · Shift 1","time":"9:00 AM - 10:30 AM","dropped":0,"questions":[{"s":"General Awareness","q":"Which of the following is a private sector organisation in India?","o":["SAIL","TISCO","ONGC","Indian Railways"],"a":1,"e":"TISCO (Tata Steel) is a private company. SAIL, ONGC and Indian Railways are public sector.","qh":"निम्नलिखित में से कौन-सा, भारत में निजी क्षेत्र का संगठन है?","oh":["सेल (SAIL)","टिस्को (TISCO)","ओएनजीसी (ONGC)","भारतीय रेल (Indian Railways)"],"eh":"TISCO (टाटा स्टील) एक निजी कंपनी है। SAIL, ONGC और भारतीय रेल सार्वजनिक क्षेत्र के हैं।"},{"s":"General Awareness","q":"Which of the following States enjoys special provisions under Article 371A due to its unique customary law and land ownership practices?","o":["Sikkim","Mizoram","Nagaland","Manipur"],"a":2,"e":"Article 371A protects Nagaland's customary law and its land ownership practices.","qh":"निम्नलिखित में से किस राज्य को अपने विशिष्ट प्रथागत विधि और भूमि स्वामित्व प्रथाओं के कारण अनुच्छेद 371A के तहत विशेष प्रावधान प्राप्त है?","oh":["सिक्किम","मिज़ोरम","नागालैंड","मणिपुर"],"eh":"अनुच्छेद 371A नागालैंड के प्रथागत कानून और भूमि स्वामित्व की परंपराओं की रक्षा करता है।"},{"s":"General Awareness","q":"Who among the following sent a telegram on 6 August 1857 stating, 'Our men are cowed by the numbers opposed to them and the endless fighting. Every village is held against us, the zamindars have risen to oppose us'?","o":["Lieutenant Colonel William Lambton","Lord Cornwallis","Lieutenant Colonel Tytler","Robert Clive"],"a":2,"e":"Lt Col Tytler sent this telegram on 6 Aug 1857, describing village-level resistance in Awadh.","qh":"निम्नलिखित में से किसने 6 अगस्त 1857 को यह लिखते हुए एक तार भेजा था कि, \"हमारे लोग विरोधियों की भारी संख्या और अंतहीन लड़ाई से डरे हुए हैं। हर गांव हमारे खिलाफ है, ज़मींदार हमारे विरोध में उठ खड़े हुए हैं\"?","oh":["लेप्टिनेंट कर्नल विलियम लैम्बटन","लॉर्ड कॉर्नवालिस","लेप्टिनेंट कर्नल टाइटलर","रॉबर्ट क्लाइव"],"eh":"लेफ्टिनेंट कर्नल टाइटलर ने 6 अगस्त 1857 को यह टेलीग्राम भेजा, जिसमें अवध में ग्राम-स्तर के प्रतिरोध का वर्णन था।"},{"s":"General Awareness","q":"What does ASCII stand for?","o":["American Standard Code for Information Interchange","Auxiliary System for Communication and Interchange","Advanced Standard Coding in Information Industry","Automated System for Computer Information Interchange"],"a":0,"e":"ASCII stands for American Standard Code for Information Interchange.","qh":"ASCII का क्या तात्पर्य है?","oh":["American Standard Code for Information Interchange (अमेरिकन स्टैंडर्ड कोड फॉर इन्फॉर्मेशन इंटरचेंज)","Auxiliary System for Communication and Interchange (ऑक्जिलरी सिस्टम फॉर कम्युनिकेशन एंड इंटरचेंज)","Advanced Standard Coding in Information Industry (एडवांस्ड स्टैंडर्ड कोडिंग इन इन्फॉर्मेशन इंडस्ट्री)","Automated System for Computer Information Interchange (ऑटोमेटेड सिस्टम फॉर कम्प्यूटर इन्फॉर्मेशन इंटरचेंज)"],"eh":"ASCII का पूर्ण रूप American Standard Code for Information Interchange है।"},{"s":"General Awareness","q":"Which of following sports events was clinched by Indian pair Manush Shah and Diya Chitale in April 2025?","o":["WTT Contender Lagos 2025","WTT Contender Tunis 2025","WTT Star Contender Ljubljana 2025","United States Smash 2025"],"a":1,"e":"Manush Shah and Diya Chitale won the mixed doubles at WTT Contender Tunis 2025.","qh":"अप्रैल 2025 में भारतीय जोड़ी मानुष शाह और दीया चितले ने निम्नलिखित में से किस खेल प्रतियोगिता का खिताब जीता था?","oh":["WTT कंटेंडर लागोस 2025 (WTT Contender Lagos 2025)","WTT कंटेंडर ट्यूनिस 2025 (WTT Contender Tunis 2025)","WTT स्टार कंटेंडर लुब्लियाना 2025 (WTT Star Contender Ljubljana 2025)","यूनाइटेड स्टेट्स स्मैश 2025 (United States Smash 2025)"],"eh":"मानुष शाह और दीया चिटाले ने WTT कंटेंडर ट्यूनिस 2025 में मिश्रित युगल जीता।"},{"s":"General Awareness","q":"What is the mass percentage of sodium hypochlorite typically present in a commercial bleaching solution?","o":["3.62%","5.46%","2.57%","10.85%"],"a":0,"e":"A standard NCERT example gives commercial bleach as 3.62% NaOCl by mass.","qh":"वाणिज्यिक विरंजन विलयन में सामान्यतः सोडियम हाइपोक्लोराइट का द्रव्यमान प्रतिशत कितना होता है?","oh":["3.62%","5.46%","2.57%","10.85%"],"eh":"NCERT के एक मानक उदाहरण में व्यावसायिक ब्लीच को द्रव्यमान के अनुसार 3.62% NaOCl बताया गया है।"},{"s":"General Awareness","q":"In which of the following cities was the Paramhansa Mandali founded to work for the abolition of caste?","o":["Kanpur","Surat","Patna","Bombay"],"a":3,"e":"The Paramhansa Mandali was founded in Bombay in 1840 to oppose caste.","qh":"जाति उन्मूलन के लिए कार्य करने हेतु परमहंस मंडली की स्थापना निम्नलिखित में से किस शहर में की गई थी?","oh":["कानपुर","सूरत","पटना","बॉम्बे"],"eh":"परमहंस मंडली की स्थापना 1840 में बंबई में जाति-प्रथा के विरोध के लिए हुई।"},{"s":"General Awareness","q":"What is the name of the Indian Light Tank that achieved a major milestone in high- altitude firing trials in December 2024?","o":["Arjun","Zorawar","Bhishma","Vijayanta"],"a":1,"e":"The indigenous light tank Zorawar completed high-altitude firing trials in December 2024.","qh":"उस इंडियन लाइट टैंक (Indian Light Tank) का नाम क्या है, जिसने दिसंबर 2024 में उच्च-ऊंचाई वाले फायरिंग परीक्षणों में एक प्रमुख उपलब्धि हासिल की?","oh":["अर्जुन","जोरावर","भीष्म","विजयंता"],"eh":"स्वदेशी हल्के टैंक ज़ोरावर ने दिसंबर 2024 में उच्च-ऊँचाई पर फायरिंग परीक्षण पूरे किए।"},{"s":"General Awareness","q":"According to the India Justice Report 2025, which two states have the highest share of women judges at the High Court level at 33%?","o":["Kerala and Andhra Pradesh","Uttar Pradesh and Odisha","Sikkim and Telangana","Chhattisgarh and Madhya Pradesh"],"a":2,"e":"India Justice Report 2025: Sikkim and Telangana had the highest share of women HC judges (33%).","qh":"इंडिया जस्टिस रिपोर्ट 2025 के अनुसार, किन दो राज्यों में उच्च न्यायालय स्तर पर महिला न्यायाधीशों की हिस्सेदारी सबसे अधिक है, जो 33% है?","eh":"इंडिया जस्टिस रिपोर्ट 2025: सिक्किम और तेलंगाना में उच्च न्यायालय की महिला न्यायाधीशों का हिस्सा सबसे अधिक (33%) था।"},{"s":"General Awareness","q":"Select the correct sequence of steps to create a new folder on the desktop?","o":["Right-click Taskbar → Select Folder → Press Enter","Click Start → Settings → New → Folder","Open File Explorer → Right-click Desktop → New Folder","Right-click Desktop → New → Folder"],"a":3,"e":"To make a folder: right-click the desktop, choose New, then Folder.","qh":"डेस्कटॉप पर नया फ़ोल्डर बनाने के लिए चरणों का सही क्रम चुनें।","oh":["Taskbar पर राइट क्लिक करें→ Folder सलेक्ट करें→ Enter दबाााएं","Start पर क्लिक करें → Settings → New → Folder पर जाएं","File Explorer ओपन करें→ Desktop पर राइट क्लिक करें → New Folder पर जाएं","Desktop पर राइट क्लिक करें → New → Folder पर जाएं"],"eh":"फ़ोल्डर बनाने के लिए: डेस्कटॉप पर राइट-क्लिक करें, New चुनें, फिर Folder।"},{"s":"General Awareness","q":"Which of the following factors DOES NOT directly influence population distribution in India?","o":["Official language","Climate","Soil fertility","Topography"],"a":0,"e":"Climate, soil and terrain shape where people live. Official language doesn't directly affect it.","qh":"निम्नलिखित में से कौन-सा कारक, भारत में जनसंख्या वितरण को प्रत्यक्ष रूप से प्रभावित नहीं करता है?","eh":"जलवायु, मृदा और भू-भाग तय करते हैं कि लोग कहाँ बसते हैं। आधिकारिक भाषा इसे सीधे प्रभावित नहीं करती।"},{"s":"General Awareness","q":"Article 6 deals with persons who migrated to India from _____.","o":["Bangladesh","Sri Lanka","Pakistan","Nepal"],"a":2,"e":"Article 6 covers citizenship of people who migrated to India from Pakistan.","qh":"अनुच्छेद 6 उन व्यक्तियों से संबंधित है जो ______ से भारत आये हैं।","oh":["बांग्लादेश","श्रीलंका","पाकिस्तान","नेपाल"],"eh":"अनुच्छेद 6 पाकिस्तान से भारत आए प्रवासियों की नागरिकता से संबंधित है।"},{"s":"General Awareness","q":"Which area of the main stem and roots contains the spongy, soft parenchyma cells that carry and store nutrients for the plant?","o":["Pith","Cortex","Metaxylem","Stele"],"a":0,"e":"The pith is the central soft parenchyma that stores and moves nutrients.","qh":"मुख्य तने और मूलों (roots) के किस क्षेत्र में स्पंजी, मुलायम मृदूतक कोशिकाएं (soft parenchyma cells) होती हैं, जो पादप के लिए पोषक तत्वों को ले जाती हैं और संग्रहीत करती हैं?","oh":["मज्जा (Pith)","वल्कुट (Cortex)","अनुदारु (Metaxylem)","रंभ (Stele)"],"eh":"मज्जा (पिथ) केंद्रीय कोमल मृदूतक है जो पोषक तत्वों का भंडारण और परिवहन करता है।"},{"s":"General Awareness","q":"Which of the following Articles of the Indian Constitution deals with Union Territories?","o":["Article 7","Article 1","Article 262","Article 239"],"a":3,"e":"Part VIII (Articles 239–241) deals with Union Territories. Article 239 covers their administration.","qh":"भारतीय संविधान का निम्नलिखित में से कौन-सा अनुच्छेद केंद्र शासित प्रदेशों से संबंधित है?","oh":["अनुच्छेद 7","अनुच्छेद 1","अनुच्छेद 262","अनुच्छेद 239"],"eh":"भाग VIII (अनुच्छेद 239–241) संघ राज्य क्षेत्रों से संबंधित है। अनुच्छेद 239 उनके प्रशासन से संबंधित है।"},{"s":"General Awareness","q":"Which of the following players completed 12,000 runs in T20 cricket and became eighth player to achieve the milestone in April 2025?","o":["Ravindra Jadeja","MS Dhoni","Rohit Sharma","Virat Kohli"],"a":2,"e":"Rohit Sharma became the 8th player to reach 12,000 T20 runs in April 2025.","qh":"निम्नलिखित में से किस खिलाड़ी ने अप्रैल 2025 में, T20 क्रिकेट में 12,000 रन पूरे किए और यह उपलब्धि हासिल करने वाला आठवां खिलाड़ी बन गया?","oh":["रवींद्र जडेजा","एम.एस. धोनी","रोहित शर्मा","विराट कोहली"],"eh":"रोहित शर्मा अप्रैल 2025 में 12,000 T20 रन बनाने वाले 8वें खिलाड़ी बने।"},{"s":"General Awareness","q":"Which organisation published the 2025 edition of the 'State of the World’s Nursing' report?","o":["International Labour Organization (ILO)","World Bank","UNICEF","World Health Organization (WHO)"],"a":3,"e":"WHO (with ICN) published the State of the World's Nursing 2025 report.","qh":"किस संगठन ने 'स्टेट ऑफ द वर्ल्ड नर्सिंग' रिपोर्ट का 2025 संस्करण जारी किया?","oh":["अंतर्राष्ट्रीय श्रम संगठन (ILO)","विश्व बैंक (World Bank)","यूनिसेफ (UNICEF)","विश्व स्वास्थ्य संगठन (WHO)"],"eh":"WHO (ICN के साथ) ने स्टेट ऑफ द वर्ल्ड्स नर्सिंग 2025 रिपोर्ट प्रकाशित की।"},{"s":"General Awareness","q":"Birch and Rhododendrons are found in which kind of forests?","o":["Tropical Evergreen and Semi Evergreen forests","Tropical Thorn forests","Montane forests","Littoral and Swamp forests"],"a":2,"e":"Birch and rhododendron grow in montane (Himalayan) forests.","qh":"बिर्च और रोडोडेंड्रोन (Birch and Rhododendron) किस प्रकार के वनों में पाए जाते हैं?","eh":"भोजपत्र (बर्च) और बुरांश (रोडोडेंड्रॉन) पर्वतीय (हिमालयी) वनों में उगते हैं।"},{"s":"General Awareness","q":"The Visuddhimagga, a key Buddhist text, was written by which of the following scholars?","o":["Nagarjuna","Aryadeva","Buddhaghosa","Vasubandhu"],"a":2,"e":"Buddhaghosa wrote the Visuddhimagga in the 5th century CE.","qh":"विसुद्धिमग्ग (Visuddhimagga), एक प्रमुख बौद्ध ग्रंथ, निम्नलिखित में से किस विद्वान द्वारा लिखा गया था?","oh":["नागार्जुन","आर्यदेव","बुद्धघोष","वासुबंधु"],"eh":"बुद्धघोष ने 5वीं शताब्दी ई. में विसुद्धिमग्ग लिखा।"},{"s":"General Awareness","q":"Who among the following presented the First Five-Year Plan on July 9, 1951?","o":["Sardar Vallabhbhai Patel","Rajendra Prasad","Jawaharlal Nehru","Purushottam Das Tandon"],"a":2,"e":"PM Jawaharlal Nehru presented the First Five-Year Plan to Parliament on 9 July 1951.","qh":"9 जुलाई, 1951 को प्रथम पंचवर्षीय योजना निम्नलिखित में से किसने प्रस्तुत की थी?","oh":["सरदार वल्लभभाई पटेल","राजेंद्र प्रसाद","जवाहरलाल नेहरू","पुरूषोत्तम दास टंडन"],"eh":"प्रधानमंत्री जवाहरलाल नेहरू ने 9 जुलाई 1951 को संसद में पहली पंचवर्षीय योजना प्रस्तुत की।"},{"s":"General Awareness","q":"Which of the following is the first of eight Anti-Submarine Warfare Shallow Water Crafts (ASW SWCs) delivered to the Indian Navy on 8 May 2025?","o":["Arnala","Kamorta","Kadmatt","Kiltan"],"a":0,"e":"Arnala, built by GRSE, was the first of eight ASW-SWCs delivered on 8 May 2025.","qh":"निम्नलिखित में से कौन-सा, 8 मई 2025 को भारतीय नौसेना को प्रदत्त आठ एंटी-सबमरीन वॉरफेयर शैलो वाटर क्राप्ट (Anti-Submarine Warfare Shallow Water Crafts - ASW SWCs) में से पहला है?","oh":["अर्नाला (Arnala)","कामोर्टा (Kamorta)","कदमत्त (Kadmatt)","किल्टन (Kiltan)"],"eh":"GRSE द्वारा निर्मित अर्नाला, 8 मई 2025 को सौंपे गए आठ ASW-SWC में पहला था।"},{"s":"General Awareness","q":"After amalgamation of 26 Regional Rural Banks (RRBs) in fourth phase of amalgamation, as notified by Department of Financial Services (DFS) in 2025, how many RRBs will be left in the country?","o":["25","28","18","21"],"a":1,"e":"After the 4th amalgamation phase, 28 RRBs remain.","qh":"वित्तीय सेवा विभाग (DFS) द्वारा 2025 में अधिसूचित चौथे चरण के 26 क्षेत्रीय ग्रामीण बैंकों (RRBs) के विलय के बाद, देश में कितने RRB बचे रहेंगे?","oh":["25","28","18","21"],"eh":"चौथे विलय चरण के बाद 28 क्षेत्रीय ग्रामीण बैंक (RRB) शेष हैं।"},{"s":"General Awareness","q":"In April 2025, a tri-services all women circumnavigation sailing expedition, 'Samudra Pradakshina' flagged off from:","o":["Durgapur","Madurai","Trivandrum","Mumbai"],"a":3,"e":"The all-women tri-service expedition 'Samudra Pradakshina' left from Mumbai.","qh":"अप्रैल 2025 में, त्रिशक्ति नारी नाविक अभियान, 'समुद्र प्रदक्षिणा' कहाँ से रवाना किया गया?","oh":["दुर्गापुर","मदुरै","त्रिवेंद्रम","मुंबई"],"eh":"सर्व-महिला त्रि-सेवा अभियान 'समुद्र प्रदक्षिणा' मुंबई से रवाना हुआ।"},{"s":"General Awareness","q":"The Kailasa Temple at Ellora is an example of which of the following types of architecture?","o":["Wooden architecture","Rock-cut architecture","Islamic architecture","Colonial architecture"],"a":1,"e":"The Kailasa Temple (Cave 16) was carved out of a single rock: rock-cut architecture.","qh":"एलोरा का कैलाश मंदिर निम्नलिखित में से किस प्रकार की वास्तुकला का उदाहरण है?","eh":"कैलाश मंदिर (गुफा 16) एक ही चट्टान को काटकर बनाया गया: शैलकृत वास्तुकला।"},{"s":"General Awareness","q":"In which of the following years did the Government of Bengal pass the Calcutta Electric Lighting Act?","o":["1895","1900","1911","1904"],"a":0,"e":"Bengal passed the Calcutta Electric Lighting Act in 1895.","qh":"निम्नलिखित में से किस वर्ष बंगाल सरकार ने कलकत्ता इलेक्ट्रिक लाइटिंग अधिनियम पारित किया?","oh":["1895","1900","1911","1904"],"eh":"बंगाल ने 1895 में कलकत्ता इलेक्ट्रिक लाइटिंग अधिनियम पारित किया।"},{"s":"General Awareness","q":"During May 2025, the 4th Europe-Africa Forum was organised in which location?","o":["Nice","Marseille","Lyon","Paris"],"a":1,"e":"The 4th Europe-Africa Forum (May 2025) was held in Marseille.","qh":"मई 2025 के दौरान, चौथा यूरोप-अफ्रीका फोरम किस स्थान पर आयोजित किया गया था?","oh":["नीस (Nice)","मार्सिले (Marseille)","ल्यों (Lyon)","पेरिस (Paris)"],"eh":"चौथा यूरोप-अफ्रीका फोरम (मई 2025) मार्सिले में आयोजित हुआ।"},{"s":"General Awareness","q":"e-NAM is a key reform aimed at integrating agricultural markets in India. What is the primary goal of the e-NAM initiative?","o":["Crop insurance","Minimum wage guarantee","Online trading of agricultural produce","Fertiliser subsidy"],"a":2,"e":"e-NAM is a pan-India online trading portal for agricultural produce.","qh":"ई-नाम (e-NAM) भारत में कृषि बाजारों को एकीकृत करने के उद्देश्य से एक महत्वपूर्ण सुधार है। ई-नाम कार्यक्रम का प्राथमिक लक्ष्य क्या है?","oh":["फसल बीमा (Crop insurance)","न्यूनतम मजदूरी गारंटी (Minimum wage guarantee)","कृषि उपज का ऑनलाइन व्यापार (Online trading of agricultural produce)","उर्वरक सब्सिडी (Fertiliser subsidy)"],"eh":"e-NAM कृषि उपज के लिए अखिल भारतीय ऑनलाइन व्यापार पोर्टल है।"},{"s":"General Awareness","q":"The RTI Act empowers citizens of India to seek information from which of the following?","o":["Private companies","Foreign embassies","Non-governmental organisations","Government departments"],"a":3,"e":"The RTI Act 2005 applies to public authorities, i.e. government departments and bodies.","qh":"RTI अधिनियम भारत के नागरिकों को निम्नलिखित में से किससे सूचना मांगने का अधिकार देता है?","eh":"RTI अधिनियम 2005 लोक प्राधिकारियों, अर्थात सरकारी विभागों और निकायों पर लागू होता है।"},{"s":"General Awareness","q":"Which programme was launched in 1953 to expand rural development more feasibly?","o":["National Extension Service (NES)","Bharat Nirman Yojana","Jawahar Rojgar Yojana","Training for Rural Youth for Self-Employment"],"a":0,"e":"The National Extension Service was launched in 1953 to take the Community Development Programme further.","qh":"1953 में ग्रामीण विकास को अधिक व्यवहार्य (feasibly) रूप से विस्तारित करने के लिए कौन-सा कार्यक्रम शुरू किया गया था?","oh":["राष्ट्रीय विस्तार सेवा (NES)","भारत निर्माण योजना","जवाहर रोजगार योजना","ग्रामीण युवाओं को स्वरोजगार के लिए प्रशिक्षण"],"eh":"सामुदायिक विकास कार्यक्रम को आगे बढ़ाने के लिए 1953 में राष्ट्रीय विस्तार सेवा शुरू की गई।"},{"s":"General Awareness","q":"Which acid was first created from inorganic materials by Hermann Kolbe in 1845?","o":["Sulphuric acid","Formic Acid","Citric Acid","Acetic Acid"],"a":3,"e":"Hermann Kolbe made acetic acid from inorganic substances in 1845.","qh":"हरमन कोल्बे ने 1845 में अकार्बनिक पदार्थों से प्रथम बार कौन-सा अम्ल बनाया था?","oh":["सल्फ्यूरिक अम्ल","फॉर्मिक अम्ल","सिट्रिक अम्ल","ऐसीटिक अम्ल"],"eh":"हरमन कोल्बे ने 1845 में अकार्बनिक पदार्थों से एसिटिक अम्ल बनाया।"},{"s":"General Awareness","q":"Western disturbances mainly affect the weather of which region in India?","o":["North-West India","Coastal Andhra Pradesh","Eastern Ghats","Deccan Plateau"],"a":0,"e":"Western disturbances bring winter rain and snow to north-west India.","qh":"पश्चिमी विक्षोभ मुख्यतः भारत के किस क्षेत्र के मौसम को प्रभावित करते हैं?","oh":["उत्तर-पश्चिम भारत","तटीय आंध्र प्रदेश","पूर्वी घाट","दक्कन का पठार"],"eh":"पश्चिमी विक्षोभ उत्तर-पश्चिम भारत में शीतकालीन वर्षा और हिमपात लाते हैं।"},{"s":"General Awareness","q":"Which of the following transportation systems was primarily developed in India to serve colonial economic interests?","o":["Inland waterways","Metro rail","Railways","Airways"],"a":2,"e":"Railways were built mainly to serve British colonial economic interests.","qh":"निम्नलिखित में से कौन-सी परिवहन प्रणाली, भारत में मुख्य रूप से औपनिवेशिक आर्थिक हितों की पूर्ति के लिए विकसित की गई थी?","eh":"रेलवे मुख्य रूप से ब्रिटिश औपनिवेशिक आर्थिक हितों की पूर्ति के लिए बनाई गई थी।"},{"s":"General Awareness","q":"During the Indus Valley Civilisation, the presence of jewellery made from precious metals and semi-precious stones in small-town settings supports the argument that ____.","o":["the civilisation was ruled by autocratic priest-kings","there was an equal access to material goods","there was strong social stratification","only the elite had access to luxury items."],"a":2,"e":"Luxury goods in small settlements point to marked social stratification.","qh":"सिंधु घाटी सभ्यता के दौरान, छोटे शहरों में कीमती धातुओं और अर्ध-कीमती पत्थरों से बने आभूषणों की उपस्थिति इस तर्क का समर्थन करती है कि ________।","eh":"छोटी बस्तियों में विलासिता की वस्तुएँ स्पष्ट सामाजिक स्तरीकरण की ओर संकेत करती हैं।"},{"s":"General Awareness","q":"In 2025, ISRO sprouted which of the following seeds in space under microgravity conditions?","o":["Soya bean seeds","Chickpea seed","Cowpea seeds","Kidney bean seeds"],"a":2,"e":"ISRO's CROPS experiment (PSLV-C60 POEM-4) sprouted cowpea seeds in microgravity.","qh":"2025 में, ISRO ने सूक्ष्म गुरुत्वाकर्षण दशाओं (microgravity conditions) के तहत अंतरिक्ष में निम्नलिखित में से कौन-से बीज अंकुरित किए?","eh":"इसरो के CROPS प्रयोग (PSLV-C60 POEM-4) में सूक्ष्म गुरुत्व में लोबिया के बीज अंकुरित हुए।"},{"s":"General Awareness","q":"Which of the following groups of people is said to have migrated into the late Indus Valley era India from Central Asia?","o":["Dravidas","Mesopotamians","Aryans","Shakas"],"a":2,"e":"The Aryans are said to have migrated from Central Asia around the late Harappan period.","qh":"निम्नलिखित में से किस समूह के लोगों के संबंध में कहा जाता है कि वे सिंधु घाटी युग के उत्तरार्ध में मध्य एशिया से भारत में आए थे?","oh":["द्रविड़ (Dravidas)","मेसोपोटामियावासी (Mesopotamians)","आर्य (Aryans)","शक (Shakas)"],"eh":"माना जाता है कि आर्य उत्तर हड़प्पा काल के आसपास मध्य एशिया से आए।"},{"s":"General Awareness","q":"What is the name of the indigenous electric trainer aircraft initiative launched by India in March 2025 to promote green aviation?","o":["Green Hawk","E-HANSA","Vayu","Shakti"],"a":1,"e":"E-HANSA is the indigenous electric trainer aircraft (CSIR-NAL) announced in 2025.","qh":"मार्च 2025 में, ग्रीन एविएशन (green aviation) को बढ़ावा देने के लिए भारत द्वारा लॉन्च की गई स्वदेशी इलेक्ट्रिक ट्रेनर वायुयान पहल का नाम क्या है?","oh":["ग्रीन हॉक (Green Hawk)","ई-हंसा (E-HANSA)","वायु (Vayu)","शक्ति (Shakti)"],"eh":"E-HANSA 2025 में घोषित स्वदेशी इलेक्ट्रिक प्रशिक्षण विमान (CSIR-NAL) है।"},{"s":"General Awareness","q":"When was the historic Paris Agreement on climate change adopted by world leaders during the UN Climate Change Conference (COP21)?","o":["1999","2005","2012","2015"],"a":3,"e":"The Paris Agreement was adopted at COP21 in December 2015.","qh":"संयुक्त राष्ट्र जलवायु परिवर्तन सम्मेलन (COP21) के दौरान विश्व के नेताओं द्वारा जलवायु परिवर्तन पर ऐतिहासिक पेरिस समझौते को कब अपनाया गया?","oh":["1999","2005","2012","2015"],"eh":"पेरिस समझौता दिसंबर 2015 में COP21 में अपनाया गया।"},{"s":"General Awareness","q":"Which of the following joint military exercises is conducted annually between the armies of India and Japan, with the sixth edition held near Mount Fuji in 2025?","o":["Maitree","Shakti","Indra","Dharma Guardian"],"a":3,"e":"Dharma Guardian is the annual India–Japan army exercise. The 2025 edition was at East Fuji.","qh":"निम्नलिखित में से कौन-सा संयुक्त सैन्य अभ्यास, भारत और जापान की सेनाओं के बीच प्रतिवर्ष आयोजित किया जाता है, जिसका छठा संस्करण, 2025 में माउंट फ़ूजी (Mount Fuji) के निकट सम्पन्न हुआ?","oh":["मैत्री","शक्ति","इंद्र","धर्म गार्डियन"],"eh":"धर्म गार्डियन भारत–जापान का वार्षिक सैन्य अभ्यास है। 2025 संस्करण ईस्ट फूजी में हुआ।"},{"s":"General Awareness","q":"Christian Stalker is the Federal Chancellor of which country?","o":["Austria","Finland","Sweden","Norway"],"a":0,"e":"Christian Stocker became Federal Chancellor of Austria in March 2025.","qh":"क्रिश्चियन स्टॉकर (Christian Stalker) किस देश के संघीय चांसलर हैं?","oh":["ऑस्ट्रिया","फिनलैंड","स्वीडन","नॉर्वे"],"eh":"क्रिश्चियन स्टॉकर मार्च 2025 में ऑस्ट्रिया के संघीय चांसलर बने।"},{"s":"General Awareness","q":"The Right to Protection in respect of conviction for offences (including protection from double jeopardy and self-incrimination) is covered under:","o":["Article 22","Article 20","Article 23","Article 21"],"a":1,"e":"Article 20 protects against ex post facto laws, double jeopardy and self-incrimination.","qh":"अपराधों के लिए दोषसिद्धि के संबंध में संरक्षण का अधिकार (दोहरा (परि)संकट और आत्म-दोषसिद्धि से संरक्षण सहित) _________के अंतर्गत आता है।","oh":["अनुच्छेद 22","अनुच्छेद 20","अनुच्छेद 23","अनुच्छेद 21"],"eh":"अनुच्छेद 20 कार्योत्तर कानूनों, दोहरे दंड और आत्म-अभिशंसन से संरक्षण देता है।"},{"s":"General Awareness","q":"Which type of weathering is primarily involved in the enrichment of bauxite and other ores?","o":["Mechanical weathering","Glacial weathering","Biological weathering","Chemical weathering"],"a":3,"e":"Chemical weathering (leaching) enriches bauxite (laterite) and similar ores.","qh":"बॉक्साइट और अन्य अयस्कों के संवर्धन में मुख्यतः किस प्रकार का अपक्षय शामिल होता है?","eh":"रासायनिक अपक्षय (निक्षालन) से बॉक्साइट (लेटराइट) और ऐसे ही अयस्क समृद्ध होते हैं।"},{"s":"Mathematics","q":"The average runs scored by a batsman in 23 matches is 43. In the next 10 matches, the batsman scored an average of 16 runs. Find his average runs scored (rounded off to two decimal places) in all the 33 matches.","o":["33.82","34.82","35.82","36.82"],"a":1,"e":"(23 × 43 + 10 × 16)/33 = 1149/33 ≈ 34.82.","qh":"एक बल्लेबाज द्वारा 23 मैचों में बनाए गए रनों का औसत 43 है। अगले 10 मैचों में, बल्लेबाज ने औसतन 16 रन बनाए। सभी 33 मैचों में उसके द्वारा बनाए गए औसत रन (दो दशमलव स्थानों तक पूणाेंकित) ज्ञात कीजिए।","oh":["33.82","34.82","35.82","36.82"],"eh":"(23 × 43 + 10 × 16)/33 = 1149/33 ≈ 34.82।"},{"s":"Mathematics","q":"","o":["11.49","9.66","16.65","16.25"],"a":0,"img":"data/img/ntpc-2025-aug-29-s1/002ma-q0.png","e":"√196 + √0.0361 − √7.29 = 14 + 0.19 − 2.7 = 11.49.","oh":["11.49","9.66","16.65","16.25"],"eh":"√196 + √0.0361 − √7.29 = 14 + 0.19 − 2.7 = 11.49।"},{"s":"Mathematics","q":"Five solid cubes, each of volume 39304 cm³, are joined end to end to form a cuboid. What is the lateral surface area (in cm²) of the cuboid?","o":["13872","13838","13905","13877"],"a":0,"e":"Each cube has side 34, so the cuboid is 170 × 34 × 34. LSA = 2(170 + 34) × 34 = 13872 cm².","qh":"पाँच ठोस घन, जिनमें से प्रत्येक का आयतन 39304 cm है, उनके सिरों को जोड़कर एक घनाभ बनाया 2 जाता है। घनाभ का पार्श्व पृष्ठीय क्षेत्रफल (cm में) कितना होगा?","oh":["13872","13838","13905","13877"],"eh":"प्रत्येक घन की भुजा 34 है, अतः घनाभ 170 × 34 × 34 है। पार्श्व पृष्ठीय क्षेत्रफल = 2(170 + 34) × 34 = 13872 cm²।"},{"s":"Mathematics","q":"Pipe A can fill a tank in 18 hours, pipe B can fill the same tank in 28 hours and pipe C can fill the same tank in 11 hours. The time taken by them to fill the same tank if they operate together is::","o":["","","",""],"a":3,"oi":["data/img/ntpc-2025-aug-29-s1/004ma-o1.png","data/img/ntpc-2025-aug-29-s1/004ma-o2.png","data/img/ntpc-2025-aug-29-s1/004ma-o3.png","data/img/ntpc-2025-aug-29-s1/004ma-o4.png"],"e":"1/18 + 1/28 + 1/11 = 505/2772 per hour, so time = 2772/505 = 5 247/505 h.","qh":"पाइप A किसी टैंक को 18 घंटे में भर सकता है, पाइप B उसी टैंक को 28 घंटे में भर सकता है और पाइप C उसी टैंक को 11 घंटे में भर सकता है। यदि वे एक-साथ चालू कर दिए जाएं, तो उसी टैंक को भरने में उन्हें कितना समय लगेगा?","eh":"1/18 + 1/28 + 1/11 = 505/2772 प्रति घंटा, अतः समय = 2772/505 = 5 247/505 घंटे।"},{"s":"Mathematics","q":"","o":["","","",""],"a":3,"img":"data/img/ntpc-2025-aug-29-s1/005ma-q0.png","oi":["data/img/ntpc-2025-aug-29-s1/005ma-o1.png","data/img/ntpc-2025-aug-29-s1/005ma-o2.png","data/img/ntpc-2025-aug-29-s1/005ma-o3.png","data/img/ntpc-2025-aug-29-s1/005ma-o4.png"],"e":"sec θ + tan θ = P, so sec θ − tan θ = 1/P. Subtracting: 2tan θ = P − 1/P, so tan θ = (P² − 1)/2P.","eh":"sec θ + tan θ = P, अतः sec θ − tan θ = 1/P। घटाने पर: 2tan θ = P − 1/P, अतः tan θ = (P² − 1)/2P।"},{"s":"Mathematics","q":"Train A leaves station M at 6:25 AM and reaches station N at 3:25 PM on the same day. Train B leaves station N at 8:25 AM and reaches station M at 2:25 PM on the same day. Find the time when trains A and B meet.","o":["11:43 AM","10:53 AM","12:13 PM","11:13 AM"],"a":3,"e":"A takes 9 h and B takes 6 h. By 8:25 A has covered 2/9. The remaining 7/9 at a combined 5/18 per hour takes 2.8 h = 2 h 48 min, so they meet at 11:13 AM.","qh":"ट्रेन A, स्टेशन M से 6:25 AM पर निकलती है और उसी दिन 3:25 PM पर स्टेशन N पर पहुँचती है। ट्रेन B, स्टेशन N से 8:25 AM पर निकलती है और उसी दिन 2:25 PM पर स्टेशन M पर पहुँचती है। ट्रेन A और B के मिलने का समय ज्ञात कीजिए।","oh":["11:43 AM","10:53 AM","12:13 PM","11:13 AM"],"eh":"A को 9 घंटे और B को 6 घंटे लगते हैं। 8:25 तक A ने 2/9 दूरी तय कर ली। शेष 7/9, संयुक्त 5/18 प्रति घंटा की दर से 2.8 घंटे = 2 घंटे 48 मिनट में तय होगी, अतः वे 11:13 AM पर मिलेंगे।"},{"s":"Mathematics","q":"The marks scored by 10 students are given below. 17, 19, 12, 20, 19, 14, 15, 18, 19, 14 The mode of the given data is:","o":["20","12","17","19"],"a":3,"e":"19 appears 3 times, the most of any value.","qh":"10 विद्यार्थियों द्वारा प्राप्त अंक नीचे दिए गए हैं। 17, 19, 12, 20, 19, 14, 15, 18, 19, 14 दिए गए आँकड़ों का बहुलक ज्ञात कीजिए।","oh":["20","12","17","19 2"],"eh":"19 तीन बार आता है, जो किसी भी अन्य मान से अधिक है।"},{"s":"Mathematics","q":"If the sum of the interior angles of a regular polygon is equal to four times the sum of its exterior angles, then what is the number of diagonals in the polygon?","o":["30","35","25","40"],"a":1,"e":"(n − 2) × 180 = 4 × 360 gives n = 10. Diagonals = 10 × 7/2 = 35.","qh":"यदि एक समबहुभुज के अंतःकोणों का योग उसके बहिष्कोणों के योग के चार गुना के बराबर है, तो बहुभुज में विकर्णों की संख्या कितनी होगी?","oh":["30","35","25","40"],"eh":"(n − 2) × 180 = 4 × 360 से n = 10। विकर्ण = 10 × 7/2 = 35।"},{"s":"Mathematics","q":"Simplify: x(2x - 3) + 2(x² - 4) + 16","o":["4x² - 3x + 8","-4x² - 3x + 8","4x² - 3x - 8","-4x² - 3x - 8"],"a":0,"e":"2x² − 3x + 2x² − 8 + 16 = 4x² − 3x + 8.","qh":"x(2x - 3) + 2(x - 4) + 16 को सरल कीजिए। 2","eh":"2x² − 3x + 2x² − 8 + 16 = 4x² − 3x + 8।"},{"s":"Mathematics","q":"A dealer offers successive discounts of 15% and 12% on a refrigerator marked at ₹25,000. What is the final selling price?","o":["₹18,900","₹18,700","₹19,000","₹18,800"],"a":1,"e":"25000 × 0.85 × 0.88 = ₹18,700.","qh":"एक विक्रेता ₹25,000 अंकित मूल्य के रेफ्रिजरेटर पर 15% और 12% की क्रमिक छूटें देता है। अंतिम विक्रय मूल्य कितना होगा?","oh":["₹18,900","₹18,700","₹19,000","₹18,800"],"eh":"25000 × 0.85 × 0.88 = ₹18,700।"},{"s":"Mathematics","q":"I bought two pendants for ₹1,200. I sold the first one at a loss of 10% and the second at a gain of 14%. If, on the whole I made neither a loss nor a gain, find the cost price (in ₹) of the first pendant.","o":["724","684","720","700"],"a":3,"e":"−0.10x + 0.14(1200 − x) = 0, so 0.24x = 168 and x = ₹700.","qh":"मैंने ₹1,200 में दो पेंडेंट खरीदे। मैंने पहला पेंडेंट 10% की हानि पर और दूसरा पेंडेंट 14% के लाभ पर बेचा। यदि कुल मिलाकर मुझे न तो हानि हुई और न ही लाभ हुआ, तो पहले पेंडेंट का क्रय मूल्य (₹ में) ज्ञात कीजिए।","oh":["724","684","720","700"],"eh":"−0.10x + 0.14(1200 − x) = 0, अतः 0.24x = 168 और x = ₹700।"},{"s":"Mathematics","q":"Two pipes can fill a cistern, individually, in 36 min and 45 min, respectively. There is a pipe located at the bottom of the cistern to empty it. If all the three pipes are opened simultaneously, then the empty cistern gets filled in 70 min. How long will the pipe at the bottom of the tank take to empty the completely filled cistern if no other pipe is then open?","o":["20 min","28 min","8 min","44 min"],"a":1,"e":"Outlet rate = 1/36 + 1/45 − 1/70 = 45/1260 = 1/28, so it empties the cistern in 28 min.","qh":"दो पाइप एक टंकी को अलग-अलग क्रमशः 36 min और 45 min में भर सकते हैं। टंकी को खाली करने के लिए उसके तल में एक पाइप लगा है। यदि तीनों पाइप एक साथ खोल दिए जाएं, तो खाली टंकी 70 min में भर जाएगी। यदि कोई अन्य पाइप नहीं खुला है, तो टंकी के तल पर लगा पाइप, पूरी तरह भरी हुई टंकी को खाली करने में कितना समय लेगा?","oh":["20 min","28 min","8 min","44 min"],"eh":"निकास दर = 1/36 + 1/45 − 1/70 = 45/1260 = 1/28, अतः यह टंकी को 28 मिनट में खाली करता है।"},{"s":"Mathematics","q":"The marked price of a shirt is ₹500. If the shopkeeper offers a 20% discount, what is the selling price of the shirt?","o":["₹480","₹400","₹450","₹420"],"a":1,"e":"500 × 0.8 = ₹400.","qh":"एक शर्ट का अंकित मूल्य ₹500 है। यदि दुकानदार 20% की छूट देता है, तो शर्ट का विक्रय मूल्य कितना होगा?","oh":["₹480","₹400","₹450","₹420"],"eh":"500 × 0.8 = ₹400।"},{"s":"Mathematics","q":"Ishaan and Meghna have to travel from Delhi to Kanpur in their respective cars. Ishaan is driving at 90 km/hr while Meghna is driving at 65 km/hr. Find the time taken by Meghna to reach Kanpur if Ishaan takes 13 hours.","o":["21 hours","27 hours","23 hours","18 hours"],"a":3,"e":"Distance = 90 × 13 = 1170 km, so Meghna takes 1170/65 = 18 h.","qh":"ईशान और मेघना को अपनी-अपनी कारों से दिल्ली से कानपुर जाना है। ईशान 90 km/hr की चाल से ड्राइव कर रहा है, जबकि मेघना 65 km/hr की चाल से ड्राइव कर रही है। यदि ईशान को कानपुर पहुँचने में 13 घंटे लगते हैं, तो मेघना को कानपुर पहुँचने में कितना समय लगेगा?","oh":["21 घंटे","27 घंटे","23 घंटे","18 घंटे"],"eh":"दूरी = 90 × 13 = 1170 km, अतः मेघना को 1170/65 = 18 घंटे लगते हैं।"},{"s":"Mathematics","q":"","o":["","","",""],"a":0,"img":"data/img/ntpc-2025-aug-29-s1/015ma-q0.png","oi":["data/img/ntpc-2025-aug-29-s1/015ma-o1.png","data/img/ntpc-2025-aug-29-s1/015ma-o2.png","data/img/ntpc-2025-aug-29-s1/015ma-o3.png","data/img/ntpc-2025-aug-29-s1/015ma-o4.png"],"e":"1/(1 + 5/6) = 6/11. 4/3 + 6/11 − 5/4 = (176 + 72 − 165)/132 = 83/132.","eh":"1/(1 + 5/6) = 6/11। 4/3 + 6/11 − 5/4 = (176 + 72 − 165)/132 = 83/132।"},{"s":"Mathematics","q":"A number, when increased by 70%, gives 3400. The number is:","o":["6000","4000","2000","1000"],"a":2,"e":"1.7x = 3400, so x = 2000.","qh":"एक संख्या में 70% की वृद्धि करने पर 3400 प्राप्त होता है। वह संख्या ज्ञात कीजिए।","oh":["6000","4000","2000","1000"],"eh":"1.7x = 3400, अतः x = 2000।"},{"s":"Mathematics","q":"If the third proportional of 8 and 20 be x, then what is the value of x?","o":["48","52","50","47"],"a":2,"e":"x = 20²/8 = 50.","qh":"यदि 8 और 20 का तृतीयानुपाती x हो, तो x का मान ज्ञात कीजिए।","oh":["48","52","50","47"],"eh":"x = 20²/8 = 50।"},{"s":"Mathematics","q":"Ritu, Sameer, and Isha invest ₹1,190, ₹1,060, and ₹1,350, respectively, to start a business. If the profit at the end of the year is ₹1,640, then what is the share of Isha in the profit?","o":["₹613","₹614","₹617","₹615"],"a":3,"e":"Isha = 1350/3600 × 1640 = ₹615.","qh":"रितु, समीर और ईशा ने क्रमशः ₹1,190, ₹1,060 और ₹1,350 का निवेश करके एक व्यवसाय शुरू किया। यदि वर्ष के अंत में लाभ ₹1,640 है, तो लाभ में ईशा का हिस्सा ज्ञात कीजिए।","oh":["₹613","₹614","₹617","₹615"],"eh":"ईशा = 1350/3600 × 1640 = ₹615।"},{"s":"Mathematics","q":"The HCF and the LCM of two numbers are 17 and 1224, respectively. If one of the numbers is 136, find the other one.","o":["85","102","153","119"],"a":2,"e":"Other number = 17 × 1224/136 = 153.","qh":"दो संख्याओं का महत्तम समापवर्तक (H.C.F.) और लघुत्तम समापवर्त्य (L.C.M.) क्रमशः 17 और 1224 है। यदि इनमें से एक संख्या 136 है, तो दूसरी संख्या ज्ञात कीजिए।","oh":["85","102","153","119"],"eh":"दूसरी संख्या = 17 × 1224/136 = 153।"},{"s":"Mathematics","q":"Find the simple interest (in ₹) on ₹4,000 at 7.5% per annum rate of interest deposited on 4 February 2024 and withdrawn on 5 April 2024.","o":["50","49","48","51"],"a":0,"e":"4 Feb to 5 Apr 2024 is 61 days (a leap year). SI = 4000 × 7.5% × 61/366 = ₹50.","qh":"₹4,000 की धनराशि पर 7.5% वार्षिक दर से 4 फरवरी 2024 से 5 अप्रैल 2024 तक की अवधि के लिए साधारण ब्याज (₹ में) ज्ञात कीजिए।","oh":["50","49 3","48","51"],"eh":"4 फरवरी से 5 अप्रैल 2024 तक 61 दिन (अधिवर्ष)। साधारण ब्याज = 4000 × 7.5% × 61/366 = ₹50।"},{"s":"Mathematics","q":"If 3 times a mother's present age is 24 years more than 9 times her daughter's present age, and 4 times the daughter's present age is 2 years less than the mother's present age, then what is the difference (in years) between the ages of the mother and the daughter?","o":["20","22","17","15"],"a":0,"e":"3M = 9D + 24 and M = 4D + 2, so D = 6 and M = 26. Difference = 20.","qh":"यदि माता की वर्तमान आयु का 3 गुना, उनकी पुत्री की वर्तमान आयु के 9 गुने से 24 वर्ष अधिक है, और पुत्री की वर्तमान आयु का 4 गुना, माता की वर्तमान आयु से 2 वर्ष कम है, तो माता और पुत्री की आयु के बीच का अंतर (वर्षों में) कितना है?","oh":["20","22","17","15"],"eh":"3M = 9D + 24 और M = 4D + 2, अतः D = 6 और M = 26। अंतर = 20।"},{"s":"Mathematics","q":"The LCM of the numbers 5.3 and 0.4 is:","o":["0.212","212","21.2","2.12"],"a":2,"e":"LCM(530, 40) = 2120, then divide by 100: 21.2.","qh":"संख्याओं 5.3 और 0.4 का लघुत्तम समापवर्त्य (LCM) ज्ञात कीजिए।","oh":["0.212","212","21.2","2.12"],"eh":"LCM(530, 40) = 2120, फिर 100 से भाग दें: 21.2।"},{"s":"Mathematics","q":"The number 563607 is divisible by which of the following?","o":["8","3","13","10"],"a":1,"e":"Digit sum = 27, which is divisible by 3.","qh":"संख्या 563607 निम्नलिखित में से किससे विभाज्य है?","oh":["8","3","13","10"],"eh":"अंकों का योग = 27, जो 3 से विभाज्य है।"},{"s":"Mathematics","q":"In an election between two candidates, 80% of the registered voters cast their vote and 19% of the votes polled were found invalid. The winning candidate got 70% of the valid votes and won the election by a margin of 1458 votes. How many voters were registered?","o":["5625","5622","5627","5623"],"a":0,"e":"Valid votes = 0.81 × 0.8R = 0.648R. Margin = 40% of valid = 0.2592R = 1458, so R = 5625.","qh":"दो उम्मीदवारों के बीच हुए एक चुनाव में, 80% पंजीकृत मतदाताओं ने मतदान किया और डाले गए मतों में से 19% अवैध पाए गए। विजयी उम्मीदवार को वैध मतों के 70% मत मिले और उसने 1458 मतों के अंतर से चुनाव जीत लिया। पंजीकृत मतदाताओं की संख्या कितनी थी?","oh":["5625","5622","5627","5623"],"eh":"वैध मत = 0.81 × 0.8R = 0.648R। अंतर = वैध मतों का 40% = 0.2592R = 1458, अतः R = 5625।"},{"s":"Mathematics","q":"Find the value of 95⁻¹⁷ ÷ 95⁹ × 95⁻¹⁵.","o":["95⁻⁴⁹","95⁻⁴¹","95⁻³⁵","95⁻⁴²"],"a":1,"e":"Add the powers: −17 − 9 − 15 = −41, giving 95⁻⁴¹.","qh":"95 −17 ÷ 95 9 × 95 −15 का मान ज्ञात कीजिए।","oh":["95 −49","95 −41","95 −35","95 −42"],"eh":"घातें जोड़ें: −17 − 9 − 15 = −41, अतः 95⁻⁴¹।"},{"s":"Mathematics","q":"The cost of 2 pens and 15 pencils is ₹286. If the cost of a pen decreases by ₹4 and the cost of a pencil increases by ₹2, then the cost of 17 pens and 3 pencils is ₹128. What is the original cost of 11 pens and 8 pencils?","o":["₹229","₹228","₹232","₹235"],"a":2,"e":"2p + 15c = 286 and 17p + 3c = 190, so p = 8 and c = 18. 11p + 8c = 88 + 144 = ₹232.","qh":"2 पेन और 15 पेंसिल की कीमत ₹286 है। यदि पेन की कीमत ₹4 प्रति पेन कम हो जाती है और पेंसिल की कीमत ₹2 प्रति पेंसिल बढ़ जाती है, तो 17 पेन और 3 पेंसिल की कीमत ₹128 हो जाती है। 11 पेन और 8 पेंसिल की मूल कीमत कितनी होगी?","oh":["₹229","₹228","₹232","₹235"],"eh":"2p + 15c = 286 और 17p + 3c = 190, अतः p = 8 और c = 18। 11p + 8c = 88 + 144 = ₹232।"},{"s":"Mathematics","q":"Salman and Vivek together invested ₹33,900 in a business. At the end of the year, out of a total profit of ₹10,000, Vivek's share was ₹3,700. What was the difference between their investments?","o":["₹8,814","₹9,547","₹8,840","₹9,551"],"a":0,"e":"Vivek's share = 37%, so he invested 12543 and Salman 21357. Difference = ₹8,814.","qh":"सलमान और विवेक ने मिलकर एक व्यवसाय में ₹33,900 का निवेश किया। वर्ष के अंत में, ₹10,000 के कुल लाभ में से, विवेक का हिस्सा ₹3,700 था। उनके निवेशों में कितना अंतर था?","oh":["₹8,814","₹9,547","₹8,840","₹9,551"],"eh":"विवेक का हिस्सा = 37%, अतः उसने 12543 और सलमान ने 21357 निवेश किए। अंतर = ₹8,814।"},{"s":"Mathematics","q":"Sapna invested ₹20,300 on simple interest, partly at the rate of 8% per annum and partly at the rate of 6% per annum. If she earns equal interests from the two investments after 6 years, then find the sum invested at the rate of 8% per annum (in ₹).","o":["8,699","8,697","8,702","8,700"],"a":3,"e":"8x = 6(20300 − x), so 14x = 121800 and x = ₹8,700.","qh":"सपना ने ₹20,300 की धनराशि में से आंशिक धनराशि 8% वार्षिक साधारण ब्याज दर और आंशिक धनराशि 6% वार्षिक साधारण ब्याज दर पर निवेश की। यदि वह 6 वर्षों के बाद दोनों निवेशों से बराबर ब्याज अर्जित करती है, तो 8% वार्षिक साधारण ब्याज दर से निवेश की गई धनराशि (₹ में) ज्ञात कीजिए।","oh":["8,699","8,697","8,702","8,700"],"eh":"8x = 6(20300 − x), अतः 14x = 121800 और x = ₹8,700।"},{"s":"Mathematics","q":"The selling price of 10 books is equal to the cost price of 16 books. Find the loss or gain percentage on these books.","o":["60% loss","","60% gain",""],"a":2,"oi":[null,"data/img/ntpc-2025-aug-29-s1/029ma-o2.png",null,"data/img/ntpc-2025-aug-29-s1/029ma-o4.png"],"e":"SP of 10 = CP of 16, so gain = 6 on a CP of 10, i.e. 60% gain.","qh":"10 पुस्तकों का विक्रय मूल्य 16 पुस्तकों के क्रय मूल्य के बराबर है। इन पुस्तकों पर हानि या लाभ प्रतिशत ज्ञात कीजिए।","eh":"10 का विक्रय मूल्य = 16 का क्रय मूल्य, अतः 10 के क्रय मूल्य पर लाभ 6, अर्थात 60% लाभ।"},{"s":"Mathematics","q":"","o":["","","",""],"a":3,"img":"data/img/ntpc-2025-aug-29-s1/030ma-q0.png","oi":["data/img/ntpc-2025-aug-29-s1/030ma-o1.png","data/img/ntpc-2025-aug-29-s1/030ma-o2.png","data/img/ntpc-2025-aug-29-s1/030ma-o3.png","data/img/ntpc-2025-aug-29-s1/030ma-o4.png"],"e":"4πr² = 4 × 3.14 × 64 = 803.84 cm².","eh":"4πr² = 4 × 3.14 × 64 = 803.84 cm²।"},{"s":"General Intelligence and Reasoning","q":"Select the set in which the numbers are related in the same way as are the numbers of the following sets. (NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into their constituent digits. E.g. 13 – Operations on 13 such as adding to/subtracting from/multiplying with 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.) (45, 80, 5) (39, 30, 24)","o":["(45, 72, 9)","(15, 10, 11)","(27, 6, 25)","(15, 0, 16)"],"a":0,"e":"2nd = 2 × (1st − 3rd): 2 × (45 − 9) = 72.","qh":"उस समुच्चय का चयन कीजिए जिसमें संख्याएं उसी प्रकार से संबंधित हैं जिस प्रकार निम्नलिखित समुच्चयों की संख्याएं संबंधित हैं। (नोट: संख्याओं को उनके घटक अंकों में तोड़े बिना संक्रियाएं पूर्ण संख्याओं पर की जानी चाहिए। उदाहरण के लिए 13 को लीजिए - 13 पर संक्रियाएं जैसे 13 में जोड़ना/घटाना/गुणा करना आदि किया जा सकता है। 13 को 1 और 3 में तोड़ना तथा फिर 1 और 3 पर गणितीय संक्रियाएं करने की अनुमति नहीं है।) (45, 80, 5) (39, 30, 24)","oh":["(45, 72, 9)","(15, 10, 11)","(27, 6, 25)","(15, 0, 16)"],"eh":"दूसरी = 2 × (पहली − तीसरी): 2 × (45 − 9) = 72।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["GJP","KNT","QIA","ORX"],"a":2,"e":"The others are +3, +6 (G→J→P). QIA doesn't fit.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से समान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह, उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["GJP","KNT","QIA","ORX"],"eh":"अन्य में +3, +6 है (G→J→P)। QIA इसमें फिट नहीं होता।"},{"s":"General Intelligence and Reasoning","q":"All 79 students in a class are standing in a row facing north. Shantanu is 37th from the right end while Vani is 23rd from the left end. How many people stand between Shantanu and Vani?","o":["20","21","18","19"],"a":3,"e":"Shantanu is 79 − 37 + 1 = 43rd from the left, so between them = 43 − 23 − 1 = 19.","qh":"एक कक्षा में, सभी 79 विद्यार्थी उत्तर दिशा की ओर अभिमुख होकर एक पंक्ति में खड़े हैं। शांतनु दाएं छोर से 37वें स्थान पर है जबकि वाणी बाएं छोर से 23वें स्थान पर है। शांतनु और वाणी के बीच कितने व्यक्ति खड़े हैं?","oh":["20","21","18","19"],"eh":"शांतनु बाएँ से 79 − 37 + 1 = 43वें स्थान पर है, अतः उनके बीच = 43 − 23 − 1 = 19।"},{"s":"General Intelligence and Reasoning","q":"Seven boxes A, B, C, D, E, F and G are kept one over the other but not necessarily in the same order. Only four boxes are kept between F and A. Only B is kept above F. Only two boxes are kept between G and E. D is kept immediately above C. E is not kept immediately above D. How many boxes are kept between E and F?","o":["3","2","1","4"],"a":0,"e":"Top to bottom: B, F, G, D, C, E, A. Three boxes are between E and F.","qh":"सात बॉक्स A, B, C, D, E, F और G एक के ऊपर एक रखे गए हैं, लेकिन जरूरी नहीं कि वे इसी क्रम में रखे गए हों। F और A के बीच केवल चार बॉक्स रखे गए हैं। F के ऊपर केवल B को रखा गया है। G और E के बीच केवल दो बॉक्स रखे गए हैं। C के ठीक ऊपर D को रखा गया है। E को D के ठीक ऊपर नहीं रखा गया है। E और F के बीच कितने बॉक्स रखे गए हैं?","oh":["3","2","1","4"],"eh":"ऊपर से नीचे: B, F, G, D, C, E, A। E और F के बीच तीन बॉक्स हैं।"},{"s":"General Intelligence and Reasoning","q":"IGBF is related to OMHL in a certain way based on the English alphabetical order. In the same way, KIDH is related to QOJN. To which of the given options is MKFJ related, following the same logic?","o":["SQLP","QSLP","QSPL","SQPL"],"a":0,"e":"Each letter moves +6: M→S, K→Q, F→L, J→P gives SQLP.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, IGBF एक निश्चित तरीके से OMHL से संबंधित है। उसी तरह KIDH, QOJN से संबंधित है। समान तर्क का अनुसरण करते हुए, MKFJ दिए गए विकल्पों में से किससे संबंधित है?","oh":["SQLP","QSLP","QSPL","SQPL"],"eh":"प्रत्येक अक्षर +6 खिसकता है: M→S, K→Q, F→L, J→P, अतः SQLP।"},{"s":"General Intelligence and Reasoning","q":"Refer to the following number and symbol series and answer the question that follows. Counting to be done from left to right only. (Note: All numbers are single digit numbers only.) (Left) 6 2 & % 5 9 # 8 $ 7 + Ω @ 1 * £ 3 4 (Right) How many such symbols are there each of which is immediately preceded by another symbol and also immediately followed by a number?","o":["4","3","5","2"],"a":1,"e":"Symbols preceded by a symbol and followed by a number: %5, @1, £3. That makes 3.","qh":"निम्नलिखित संख्या और प्रतीक श्रृंखला का संदर्भ लें और उसके बाद दिए गए प्रश्न का उत्तर दें। गिनती केवल बाएं से दाएं की जानी चाहिए। (नोट: सभी संख्याएँ केवल एकल अंक वाली संख्याएँ हैं।) (बाएं) 6 2 & % 5 9 # 8 $ 7 + Ω @ 1 * £ 3 4 (दाएं) ऐसे कितने प्रतीक हैं जिनमें से प्रत्येक के ठीक पहले एक अन्य प्रतीक तथा ठीक बाद एक संख्या है?","oh":["4","3","5","2"],"eh":"वे प्रतीक जिनसे पहले प्रतीक और बाद में संख्या है: %5, @1, £3। कुल 3।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘life is mysterious’ is coded as ‘qr gt ob’ and ‘give his life’ is coded as ‘ob ft rd’. How is ‘life’ coded in the given language?","o":["ft","rd","qr","ob"],"a":3,"e":"'life' is the common word and 'ob' is the common code.","qh":"किसी निश्चित कूट भाषा में, ‘life is mysterious’ को ‘qr gt ob’ के रूप में कूटबद्ध किया गया है और ‘give his life’ को ‘ob ft rd’ के रूप में कूटबद्ध किया गया है। दी गई भाषा में ‘life’ को कैसे कूटबद्ध किया जाएगा?","oh":["ft","rd","qr","ob"],"eh":"'life' उभयनिष्ठ शब्द है और 'ob' उभयनिष्ठ कूट है।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘PEST’ is coded as ‘4597’ and ‘HEPS’ is coded as ‘7654’. What is the code for ‘H’ in the given code language?","o":["6","4","5","7"],"a":0,"e":"P, E, S share 4, 5, 7, so H = 6.","qh":"एक निश्चित कूट भाषा में, ‘PEST’ को ‘4597’ और ‘HEPS’ को ‘7654’ के रूप में कूटबद्ध किया जाता है। दी गई कूट भाषा में ‘H’ का कूट क्या होगा?","oh":["6","4","5","7"],"eh":"P, E, S के कूट 4, 5, 7 उभयनिष्ठ हैं, अतः H = 6।"},{"s":"General Intelligence and Reasoning","q":"Which of the following letter-number clusters will replace the question mark (?) in the given series to make it logically complete? BGS 153, XLO 142, TQK 131, PVG 120, LAC 109, ?","o":["FHA 98","GDZ 101","IDX 101","HFY 98"],"a":3,"e":"Letters −4, +5, −4 (L→H, A→F, C→Y) and the number −11, giving HFY 98.","qh":"दी गई श्रृंखला को तार्किक रूप से पूर्ण बनाने के लिए प्रश्न-चिह्न (?) को निम्नलिखित में से किस अक्षर- संख्या समूह द्वारा प्रतिस्थापित किया जाना चाहिए। BGS 153, XLO 142, TQK 131, PVG 120, LAC 109, ?","oh":["FHA 98","GDZ 101","IDX 101","HFY 98"],"eh":"अक्षर −4, +5, −4 (L→H, A→F, C→Y) और संख्या −11, अतः HFY 98।"},{"s":"General Intelligence and Reasoning","q":"Read the given statement(s) and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusion(s) logically follow(s) from the statement(s). Statements: All Wolves are Rhinoceroses. No Rhinoceroses are Kangaroos. Conclusions: I: No Kangaroos are Wolves. II: Some Kangaroos are Wolves.","o":["Only conclusion (I) follows.","Neither conclusion (I) nor (II) follows.","Only conclusion (II) follows.","Both conclusions (I) and (II) follow."],"a":0,"e":"Wolves ⊂ Rhinoceroses and no Rhinoceros is a Kangaroo, so no Kangaroo is a Wolf. Only (I) follows.","qh":"दिए गए कथनों और निष्कर्षों को ध्यानपूर्वक पढ़िए। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होती हो, निर्णय लीजिए कि दिए गए निष्कर्षों में से कौन- से निष्कर्ष, कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: सभी भेड़िये, गैंडे हैं। कोई गैंडे, कंगारू नहीं है। निष्कर्ष: I: कोई कंगारू, भेड़िये नहीं है। II: कुछ कंगारू, भेड़िये हैं।","oh":["केवल निष्कर्ष (I) अनुसरण करता है।","न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","केवल निष्कर्ष (II) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।"],"eh":"भेड़िये ⊂ गैंडे और कोई गैंडा कंगारू नहीं है, अतः कोई कंगारू भेड़िया नहीं है। केवल (I) अनुसरण करता है।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["MOK","OQM","OSP","DFB"],"a":2,"e":"The others are +2, −4 (M→O→K). OSP is +4, −3.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह, उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["MOK","OQM","OSP","DFB"],"eh":"अन्य में +2, −4 है (M→O→K)। OSP में +4, −3 है।"},{"s":"General Intelligence and Reasoning","q":"Seven boxes, A, B, C, D, K, L and O, are kept one over the other, but not necessarily in the same order. Only two boxes are kept below O. Only one box is kept above L. Only one box is kept between L and D. C is kept immediately above K. A is kept at some place below B. How many boxes are kept between B and C?","o":["Four","Two","Three","One"],"a":0,"e":"Top to bottom: B, L, A, D, O, C, K. Four boxes are between B and C.","qh":"सात बॉक्स, A, B, C, D, K, L और O, एक के ऊपर एक करके रखे गए हैं, लेकिन जरूरी नहीं कि वे इसी क्रम में हों। O के नीचे केवल दो बॉक्स रखे गए हैं। L के ऊपर केवल एक बॉक्स रखा गया है। L और D के बीच केवल एक बॉक्स रखा गया है। C को K के ठीक ऊपर रखा गया है। A को B के नीचे किसी स्थान पर रखा गया है। B और C के बीच कितने बॉक्स रखे गए हैं?","oh":["चार","दो","तीन","एक"],"eh":"ऊपर से नीचे: B, L, A, D, O, C, K। B और C के बीच चार बॉक्स हैं।"},{"s":"General Intelligence and Reasoning","q":"What will come in the place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged? 25 − 9 × 3 + 4 ÷ 2 = ?","o":["20","17","19","18"],"a":0,"e":"Becomes 25 + 9 ÷ 3 − 4 × 2 = 25 + 3 − 8 = 20.","qh":"यदि ‘+’ और ‘−’ को परस्पर बदल दिया जाए तथा ‘×’ और ‘÷’ को परस्पर बदल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न चिन्ह (?) के स्थान पर क्या आएगा? 25 − 9 × 3 + 4 ÷ 2 = ?","oh":["20","17","19","18"],"eh":"यह 25 + 9 ÷ 3 − 4 × 2 = 25 + 3 − 8 = 20 बन जाता है।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 991 990 992 991 993 992 994 ?","o":["993","996","995","992"],"a":0,"e":"Alternately −1 and +2: 994 − 1 = 993.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आएगा? 991 990 992 991 993 992 994 ?","oh":["993","996","995","992"],"eh":"बारी-बारी से −1 और +2: 994 − 1 = 993।"},{"s":"General Intelligence and Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements. Statements: All doors are carpets. No carpet is a mat. Conclusions: (I) No door is a mat. (II) No mat is a carpet.","o":["Only conclusion (II) follows.","Only conclusion (I) follows.","Neither conclusion (I) nor (II) follows.","Both conclusions (I) and (II) follow."],"a":3,"e":"No door can be a mat (doors ⊂ carpets), and 'no carpet is a mat' converts to 'no mat is a carpet'. Both follow.","qh":"दिए गए कथनों और निष्कर्षों को ध्यानपूर्वक पढ़ें। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होती हो, तय करें कि दिए गए निष्कर्षों में से कौन-से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: सभी दरवाज़े, कालीन हैं। कोई कालीन, चटाई नहीं है। निष्कर्ष: (I) कोई दरवाज़ा, चटाई नहीं है। (II) कोई चटाई, कालीन नहीं है।","oh":["केवल निष्कर्ष (II) अनुसरण करता है।","केवल निष्कर्ष (I) अनुसरण करता है।","न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।"],"eh":"कोई दरवाज़ा चटाई नहीं हो सकता (दरवाज़े ⊂ कालीन), और 'कोई कालीन चटाई नहीं है' का परिवर्तन 'कोई चटाई कालीन नहीं है' है। दोनों अनुसरण करते हैं।"},{"s":"General Intelligence and Reasoning","q":"B is the brother of A. A is the wife of C. C is the father of K. K is the mother of S. How is B related to S?","o":["Mother's mother's sister","Mother's sister's daughter","Mother's mother's brother","Mother's sister's son"],"a":2,"e":"A is K's mother and K is S's mother, so A is S's mother's mother. B is S's mother's mother's brother.","qh":"B, A का भाई है। A, C की पत्नी है। C, K का पिता है। K, S की माता है। B का S से क्या संबंध है?","eh":"A, K की माता है और K, S की माता है, अतः A, S की नानी है। B, S की नानी का भाई है।"},{"s":"General Intelligence and Reasoning","q":"Vignesh starts from Point Y and drives 17 km towards south. He then takes a left turn, drives 25 km. He then turns right and drives 9 km. He takes a final right turn, drives 25 km and stops at Point Z. How far (shortest distance) and towards which direction should he drive in order to reach Point Y again? (All turns are 90° turns only unless specified.)","o":["26 km towards east","26 km towards north","19 km towards south","13 km towards west"],"a":1,"e":"Net position: 26 km south of Y (east 25, then west 25), so he drives 26 km north.","qh":"विग्नेश, बिंदु Y से ड्राइव करना शुरू करता है और दक्षिण की ओर 17 km ड्राइव करता है। फिर वह बाएं मुड़ता है और 25 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 9 km ड्राइव करता है। वह अंत में दाएं मुड़ता है और 25 km ड्राइव करके बिंदु Z पर रुक जाता है। बिंदु Y पर वापस पहुंचने के लिए उसे कितनी दूरी (न्यूनतम दूरी) और किस दिशा में ड्राइव करना चाहिए? (जब तक निर्दिष्ट न किया जाए, सभी मोड़ केवल 90° के मोड़ हैं।)","oh":["26 km, पूर्व की ओर","26 km, उत्तर की ओर","19 km, दक्षिण की ओर","13 km, पश्चिम की ओर"],"eh":"शुद्ध स्थिति: Y से 26 km दक्षिण (पूर्व 25, फिर पश्चिम 25), अतः वह 26 km उत्तर जाता है।"},{"s":"General Intelligence and Reasoning","q":"What will come in place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged? 12 ÷ 6 + 28 × 4 − 11 = ?","o":["72","76","74","78"],"a":1,"e":"Becomes 12 × 6 − 28 ÷ 4 + 11 = 72 − 7 + 11 = 76.","qh":"यदि ‘+’ और ‘−’ को आपस में बदल दिया जाए तथा ‘×’ और ‘÷’ को आपस में बदल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न-चिह्न (?) के स्थान पर क्या आएगा? 12 ÷ 6 + 28 × 4 − 11 = ?","oh":["72","76","74","78"],"eh":"यह 12 × 6 − 28 ÷ 4 + 11 = 72 − 7 + 11 = 76 बन जाता है।"},{"s":"General Intelligence and Reasoning","q":"L, M, N, O, Q, R and S are sitting around a circular table, facing the centre of the table. Only two people sit between O and R when counted from the right of O. Only two people sit between R and M. Only three people sit between O and N. L sits to the immediate left of Q. Who sits third to the left of S?","o":["Q","R","L","N"],"a":0,"e":"Going left from O: O, M, S, N, R, Q, L. Third to the left of S is Q.","qh":"L, M, N, O, Q, R और S एक गोल मेज के परितः केंद्र की ओर अभिमुख होकर बैठे हैं। O के दाईं ओर से गिनती करने पर, O और R के बीच केवल दो व्यक्ति बैठे हैं। R और M के बीच केवल दो व्यक्ति बैठे हैं। O और N के बीच केवल तीन व्यक्ति बैठे हैं। L, Q के ठीक बाईं ओर पड़ोस में बैठा है। S के बाईं ओर तीसरे स्थान पर कौन बैठा है?","oh":["Q","R","L","N"],"eh":"O से बाईं ओर: O, M, S, N, R, Q, L। S के बाएँ से तीसरा Q है।"},{"s":"General Intelligence and Reasoning","q":"Each of the digits in the number 5936814 is arranged in ascending order from left to right. What will be the sum of the digits which are second from the left and fourth from the right in the new number thus formed?","o":["13","9","11","8"],"a":3,"e":"Ascending: 1345689. Second from the left is 3 and fourth from the right is 5, so 3 + 5 = 8.","qh":"संख्या 5936814 में प्रत्येक अंक को बाएँ से दाएँ आरोही क्रम में व्यवस्थित किया जाता है। इस प्रकार बनी नई संख्या में बाएँ से दूसरे अंक और दाएँ से चौथे अंक का योग कितना होगा?","oh":["13","9","11","8"],"eh":"आरोही: 1345689। बाएँ से दूसरा 3 और दाएँ से चौथा 5 है, अतः 3 + 5 = 8।"},{"s":"General Intelligence and Reasoning","q":"Nilesh starts from Point Y and drives 17 km towards the north. He then takes a left turn and drives 31 km, then turns left and drives 45 km. He then takes a right turn and drives 23 km. He takes a right turn, drives 28 km and stops at Point Z. How far (shortest distance) and in which direction should he drive in order to reach Point Y again? (All turns are 90-degree turns only unless specified.)","o":["61 km towards the west","58 km towards the west","54 km towards the east","49 km towards the east"],"a":2,"e":"Net position: 54 km west of Y (y: 17 − 45 + 28 = 0), so he drives 54 km east.","qh":"नीलेश, बिंदु Y से ड्राइव करना शुरू करता है और उत्तर की ओर 17 km ड्राइव करता है। फिर वह बाएं मुड़ता है और 31 km ड्राइव करता है, फिर बाएं मुड़ता है और 45 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 23 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 28 km ड्राइव करके बिंदु Z पर रुक जाता है। बिंदु Y पर वापस पहुंचने के लिए उसे कितनी दूरी (न्यूनतम दूरी) और किस दिशा में ड्राइव करना चाहिए? (जब तक निर्दिष्ट न किया जाए, सभी मोड़ केवल 90-डिग्री के मोड़ हैं।)","oh":["61 km, पश्चिम की ओर","58 km, पश्चिम की ओर","54 km, पूर्व की ओर","49 km, पूर्व की ओर"],"eh":"शुद्ध स्थिति: Y से 54 km पश्चिम (y: 17 − 45 + 28 = 0), अतः वह 54 km पूर्व जाता है।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series based on the English alphabetical order? DKC ZGY ? RYQ NUM","o":["UDU","VCV","VCU","VDU"],"a":2,"e":"Each letter moves −4: Z→V, G→C, Y→U gives VCU.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर दी गई श्रृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? DKC ZGY ? RYQ NUM","oh":["UDU","VCV","VCU","VDU"],"eh":"प्रत्येक अक्षर −4 खिसकता है: Z→V, G→C, Y→U, अतः VCU।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 112 101 90 79 68 ?","o":["56","54","55","57"],"a":3,"e":"Each term is −11, so 68 − 11 = 57.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आना चाहिए? 112 101 90 79 68 ?","oh":["56","54","55","57"],"eh":"प्रत्येक पद −11 घटता है, अतः 68 − 11 = 57।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-cluster pairs are alike in a certain way and thus form a group. Which letter-cluster pair DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["MC - PY","YV - CR","PF - SB","JB - MX"],"a":1,"e":"The others are +3, −4 (M→P, C→Y). YV - CR starts with Y→C, which is +4.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, निम्नलिखित चार अक्षर-समूह युग्मों में से तीन एक निश्चित तरीके से समान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह युग्म, उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह युग्म, व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["MC - PY","YV - CR","PF - SB","JB - MX"],"eh":"अन्य में +3, −4 है (M→P, C→Y)। YV - CR की शुरुआत Y→C से होती है, जो +4 है।"},{"s":"General Intelligence and Reasoning","q":"If 2 is added to each even digit and 1 is subtracted from each odd digit in the number 9524367, then how many digits will appear more than once in the new number thus formed?","o":["Two","None","Three","One"],"a":2,"e":"9524367 becomes 8446286. 8, 4 and 6 each repeat, so three digits.","qh":"यदि संख्या 9524367 के प्रत्येक सम अंक में 2 जोड़ा जाए तथा प्रत्येक विषम अंक में से 1 घटाया जाए, तो इस प्रकार बनी नई संख्या में कितने अंक एक से अधिक बार आएंगे?","oh":["दो","एक भी नहीं","तीन","एक"],"eh":"9524367, 8446286 बन जाता है। 8, 4 और 6 प्रत्येक दोहराए गए हैं, अतः तीन अंक।"},{"s":"General Intelligence and Reasoning","q":"Seven people, A, B, C, D, P, Q and R, are sitting in a row, facing north. Only two people sit to the left of B. Only three people sit between B and Q. Only one person sits between Q and P. D sits to the immediate left of C. R is not an immediate neighbour of Q. How many people sit to the right of A?","o":["Three","One","Two","Four"],"a":1,"e":"The order is D, C, B, R, P, A, Q. One person (Q) is to the right of A.","qh":"सात व्यक्ति A, B, C, D, P, Q और R एक पंक्ति में उत्तर की ओर अभिमुख होकर बैठे हैं। B के बाईं ओर केवल दो व्यक्ति बैठे हैं। B और Q के बीच केवल तीन व्यक्ति बैठे हैं। Q और P के बीच केवल एक व्यक्ति बैठा है। D, C के ठीक बाईं ओर पड़ोस में बैठा है। R, Q का निकटतम पड़ोसी नहीं है। A के दाईं ओर कितने व्यक्ति बैठे हैं?","oh":["तीन","एक","दो","चार"],"eh":"क्रम D, C, B, R, P, A, Q है। A के दाएँ एक व्यक्ति (Q) है।"},{"s":"General Intelligence and Reasoning","q":"In the following triads, each group of letters is related to the subsequent one following a certain logic. Select from the given options, the one which follows the same logic. RUST - URST - RSTU KITE - IKTE - KTEI","o":["MINK - IMNK - KINM","MANY - AMNY - MNYA","SPOT - PSOT - POTS","VEIN - VIEN - NIEV"],"a":1,"e":"Swap the first two letters, then write the 1st letter + 3rd, 4th + 2nd. MANY → AMNY → MNYA.","qh":"निम्नलिखित त्रिकों में, अक्षरों का प्रत्येक समूह एक निश्चित तर्क का अनुसरण करते हुए अगले समूह से संबंधित है। दिए गए विकल्पों में से उस विकल्प का चयन कीजिए जो समान तर्क का अनुसरण करता हो। RUST - URST - RSTU KITE - IKTE - KTEI","oh":["MINK - IMNK - KINM","MANY - AMNY - MNYA","SPOT - PSOT - POTS","VEIN - VIEN - NIEV"],"eh":"पहले दो अक्षरों की अदला-बदली करें, फिर पहला अक्षर + तीसरा, चौथा + दूसरा लिखें। MANY → AMNY → MNYA।"},{"s":"General Intelligence and Reasoning","q":"Select the pair that follows the same pattern as that followed by the two pairs given below. Both pairs follow the same pattern. SDF : RCE MVZ : LUY","o":["BGJ : AFI","RTY : SZU","ADH : BFJ","CNR : DOS"],"a":0,"e":"Each letter moves −1: B→A, G→F, J→I.","qh":"उस युग्म का चयन कीजिए जो नीचे दिए गए दो युग्मों के समान पैटर्न का अनुसरण करता है। दोनों युग्म समान पैटर्न का अनुसरण करते हैं। SDF : RCE MVZ : LUY","oh":["BGJ : AFI","RTY : SZU","ADH : BFJ","CNR : DOS"],"eh":"प्रत्येक अक्षर −1 खिसकता है: B→A, G→F, J→I।"},{"s":"General Intelligence and Reasoning","q":"This question is based on the five, three-digit numbers given below. (Left) 538 745 317 853 276 (Right) (Example- 697 – First digit = 6, second digit = 9 and third digit = 7) (NOTE: All operations to be done from left to right.) What will be the resultant if the third digit of the highest number is added to the second digit of the lowest number?","o":["9","8","11","10"],"a":3,"e":"Highest is 853 (third digit 3) and lowest is 276 (second digit 7): 3 + 7 = 10.","qh":"यह प्रश्न नीचे दी गई पाँच, तीन-अंकीय संख्याओं पर आधारित है। (बाएं) 538 745 317 853 276 (दाएं) (उदाहरण- 697 - पहला अंक = 6, दूसरा अंक = 9 और तीसरा अंक = 7) (नोट: सभी संक्रियाएं बाएं से दाएं की जानी हैं।) यदि सबसे बड़ी संख्या के तीसरे अंक को सबसे छोटी संख्या के दूसरे अंक में जोड़ा जाए तो परिणाम क्या होगा?","oh":["9","8","11","10"],"eh":"सबसे बड़ी 853 (तीसरा अंक 3) और सबसे छोटी 276 (दूसरा अंक 7) है: 3 + 7 = 10।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 4 8 24 96 ? 2880","o":["240","410","480","320"],"a":2,"e":"Multiply by ×2, ×3, ×4, ×5, ×6: 96 × 5 = 480, and 480 × 6 = 2880.","qh":"दी गई शृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? 4 8 24 96 ? 2880","oh":["240","410","480","320"],"eh":"×2, ×3, ×4, ×5, ×6 से गुणा करें: 96 × 5 = 480, और 480 × 6 = 2880।"}]});
